//! Experimental AI Remove: the Remove tool's third mode, where a painted area
//! is regenerated by an extension's retouch generator (a hosted model with the
//! user's own key) and kept as a Generate spot whose patch renders without the
//! extension. Everything here is the app's side of one request: what it
//! captures, when its result may still be applied, and what the tool says.
//!
//! The generators are extensions' ([`retouch_generator`]). A request has its
//! region rendered and its answer inverted on a worker thread of its own, so
//! neither does pixel work on the UI thread, and its outcome becomes one
//! History step ("AI Remove") that appends the spot, so edits made meanwhile
//! survive. It applies only while what it was made from still holds
//! ([`Guard`]): the same photo, load, file, catalog photo, decoded image, AI
//! Denoise source and noise reduction, and the same spots, red eye and Spot
//! Removal and Red Eye panel state. Otherwise it is dropped with
//! [`STALE`], never asked again by itself: each request is one paid call.
//!
//! Every ending clears busy: success, failure, a worker job that panicked or
//! a worker gone (their fallback events), Cancel, the extension disabled,
//! crashed or reloaded (its lifecycle moved), the deadline, another photo or
//! catalog, and quitting. Patches not taken are let go of unless the edit,
//! its History or Before names them, as Select Subject's rasters are.
//!
//! [`retouch_generator`]: crate::app::extensions::retouch_generator
use crate::app::Editor;
use crate::app::develop::tools::subject_mask::Worker;
use crate::app::extensions::retouch_generator::{self, Offer};
use crate::app::task::{Stopping, Task};
use crate::camera_data::CameraImage;
use crate::model::recipe::Recipe;
use crate::model::retouch::{RetouchMode, RetouchOp, RetouchPatch};
use rawmakase_extensions::protocol::RemoteError;
use rawmakase_extensions::protocol::method::{RetouchGenerate, RetouchGenerated};
use rawmakase_extensions::shm::Returned;
use serde_json::Value;
use std::sync::Arc;
use std::sync::atomic::AtomicBool;

/// What a result made from pixels that have since changed says.
pub(in crate::app) const STALE: &str = "The photo changed while removing; paint again";

/// Why AI Remove made no spot; the drawer says so.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) enum Failure {
    Cancelled,
    /// The extension has to be set up first (an API key); its message.
    NeedsSetup(String),
    /// The service can't be reached or won't work now; why.
    Unavailable(String),
    /// The service declined the region's content; why.
    Refused(String),
    Failed(String),
}
impl Failure {
    pub(in crate::app) fn message(&self) -> String {
        match self {
            Self::Cancelled => "AI Remove cancelled".into(),
            Self::NeedsSetup(why) => format!("AI Remove needs setting up: {why}"),
            Self::Unavailable(why) => format!("AI Remove is unavailable: {why}"),
            Self::Refused(why) => format!("The service declined this area: {why}"),
            Self::Failed(why) => format!("AI Remove failed: {why}"),
        }
    }
}

/// A patch a request produced, registered unsaved in the asset store.
#[derive(Debug)]
pub(crate) struct Generated {
    pub(crate) patch: RetouchPatch,
}

/// A request's outcome, tagged with what it was started for.
pub(crate) struct Done {
    pub(crate) load: u64,
    pub(crate) generation: u64,
    pub(crate) result: Result<Generated, Failure>,
}

/// What must still hold when a result arrives for it to be applied, read from
/// the editor when the request starts and again at completion.
#[derive(Clone, Debug, PartialEq)]
pub(in crate::app) struct Guard {
    /// The spots, red eye, camera exposure and the Spot Removal and Red Eye
    /// panels' state ([`subject_mask::content`]).
    ///
    /// [`subject_mask::content`]: crate::app::develop::tools::subject_mask::content
    content: u64,
    /// The settings noise reduction renders with (AI Denoise's switch and
    /// Amount, Color and luminance noise reduction).
    denoise: String,
    /// The AI Denoise source the region was made from, by identity.
    ai: Option<crate::develop::AiSource>,
    /// The decoded image, by identity.
    image: usize,
    load: u64,
    file: Option<crate::storage::Identity>,
    /// The catalog's location and the photo.
    photo: Option<(String, crate::ids::PhotoId)>,
}

/// The noise reduction settings, as a value to compare.
fn denoise(r: &Recipe) -> String {
    serde_json::to_string(&(
        &r.ai_denoise,
        r.noise_luma.to_bits(),
        r.noise_chroma.to_bits(),
        r.effects.chroma_detail.to_bits(),
        r.effects.chroma_smoothness.to_bits(),
        r.effects.luma_detail.to_bits(),
        r.effects.luma_contrast.to_bits(),
    ))
    .unwrap_or_default()
}

struct Pending {
    offer: Offer,
    /// The spot to add: the painted shape, with the tool's feather and opacity.
    op: RetouchOp,
    guard: Guard,
    load: u64,
    generation: u64,
    cancel: Arc<AtomicBool>,
    /// The extension's lifecycle when it started: once it moves (disabled,
    /// uninstalled, reloaded, crashed, hung) the request is void.
    lifecycle: u64,
    ai_denoise: bool,
    /// From when it is sent until its outcome: the host's ticket, what it
    /// asked, and what the answer is inverted through.
    sent: Option<Sent>,
}

struct Sent {
    ticket: u64,
    asked: RetouchGenerate,
    rendition: crate::develop::retouch::rendition::Rendition,
    region: crate::develop::retouch::rendition::Region,
}

/// A request waiting for the user's consent to send pixels to the service.
#[derive(Clone, Debug, PartialEq)]
pub(in crate::app) struct Consent {
    pub(in crate::app) offer: Offer,
    pub(in crate::app) op: RetouchOp,
}

pub(in crate::app) struct AiRemove {
    task: Task,
    pending: Option<Pending>,
    worker: Worker,
    /// What the last attempt ended in, for the drawer, until the next.
    pub(in crate::app) failure: Option<Failure>,
    /// A request waiting for the user to agree to its uploads.
    pub(in crate::app) consent: Option<Consent>,
    /// Patches of results not taken while another request ran, to let go of
    /// once none runs.
    deferred: Vec<String>,
    /// Requests given up on, by extension and ticket, for the host to cancel
    /// at its next poll.
    withdrawn: Vec<(String, u64)>,
}
impl Default for AiRemove {
    fn default() -> Self {
        Self {
            task: Task::default(),
            pending: None,
            worker: Worker::named("ai-remove"),
            failure: None,
            consent: None,
            deferred: Vec::new(),
            withdrawn: Vec::new(),
        }
    }
}

impl AiRemove {
    /// The shape being removed, while a request runs.
    pub(in crate::app) fn running(&self) -> Option<&RetouchOp> {
        self.pending.as_ref().map(|p| &p.op)
    }
    /// Stops the running request, whatever it is for. One in flight is
    /// withdrawn: its answer can't apply any more, and the host cancels it at
    /// the program.
    pub(in crate::app) fn cancel(&mut self) {
        self.task.invalidate();
        if let Some(Pending {
            offer,
            sent: Some(sent),
            ..
        }) = self.pending.take()
        {
            self.withdrawn.push((offer.extension, sent.ticket));
        }
    }
    pub(in crate::app) fn take_withdrawn(&mut self) -> Vec<(String, u64)> {
        std::mem::take(&mut self.withdrawn)
    }
    /// The photo changed: nothing asked for the previous one applies.
    pub(in crate::app) fn clear_document(&mut self) {
        self.cancel();
        self.failure = None;
        self.consent = None;
    }
    /// The thread to wait for when quitting, handed to the shared deadline.
    pub(in crate::app) fn stop(&mut self) -> Vec<Stopping> {
        self.cancel();
        self.consent = None;
        vec![self.worker.stop()]
    }
}

impl Editor {
    /// The retouch generator AI Remove uses: the first an enabled extension
    /// offers, with why it can't run now.
    pub(in crate::app) fn ai_remove_offer(&self) -> Option<(Offer, Option<String>)> {
        self.extensions.retouch_offers().into_iter().next()
    }
    /// Why AI Remove can't run on the open photo now, for the tool to say.
    pub(in crate::app) fn ai_remove_unavailable(&self) -> Option<String> {
        if self.library.is_none() || self.document.catalog_photo.is_none() {
            return Some("Add this photo to a catalog to use AI Remove".into());
        }
        let Some(image) = self.document.full() else {
            return Some("Available once the photo has finished developing".into());
        };
        if self.document.edit.save_state().is_protected() {
            return Some("This edit is protected and cannot be changed here".into());
        }
        let recipe = self.document.edit.recipe();
        if let Some(why) = crate::develop::retouch::rendition::refusal(image, recipe) {
            return Some(why.into());
        }
        if recipe.ai_denoise.renders() && !self.document.ai.is_complete() {
            return Some("Available once AI Denoise has finished".into());
        }
        None
    }
    /// What must hold for a result to apply, read now.
    fn ai_remove_guard(&self, image: &Arc<CameraImage>, recipe: &Recipe) -> Guard {
        Guard {
            content: crate::app::develop::tools::subject_mask::content(recipe),
            denoise: denoise(recipe),
            ai: self.document.ai_source(image, &recipe.ai_denoise),
            image: Arc::as_ptr(image) as usize,
            load: self.document.load_id(),
            file: self.document.file.clone(),
            photo: self
                .library
                .as_ref()
                .zip(self.document.catalog_photo)
                .map(|(l, id)| (format!("{:?}", l.session.catalog().location()), id)),
        }
    }
    /// The guard as it would be read now, if the photo is still decoded.
    fn ai_remove_guard_now(&self) -> Option<Guard> {
        let image = self.document.full()?.clone();
        Some(self.ai_remove_guard(&image, self.document.edit.recipe()))
    }

    /// The painted shape `op` is to be regenerated: asks for consent first
    /// when the generator uploads and the user hasn't agreed yet, then starts.
    pub(in crate::app) fn request_ai_remove(&mut self, op: RetouchOp) {
        match self.ai_remove_offer() {
            Some((offer, why)) => self.request_ai_remove_with(offer, why, op),
            None => self
                .messages
                .warn("Install AI Remove in Preferences > Extensions to use it"),
        }
    }

    /// [`Editor::request_ai_remove`] with `offer`'s generator, which can't run
    /// for `why` when that is some.
    pub(in crate::app) fn request_ai_remove_with(
        &mut self,
        offer: Offer,
        why: Option<String>,
        mut op: RetouchOp,
    ) {
        self.context.request_repaint();
        if self.ai_remove.pending.is_some() {
            self.messages
                .note("AI Remove is still working on the last area");
            return;
        }
        if let Some(why) = self.ai_remove_unavailable() {
            self.messages.warn(why);
            return;
        }
        if self.document.edit.recipe().retouch.len() >= crate::model::retouch::MAX_OPS {
            self.messages.warn("Too many spots on this photo");
            return;
        }
        if let Some(why) = why {
            self.messages.warn(why);
            return;
        }
        op.mode = RetouchMode::Generate;
        op.offset = [0.; 2];
        op.patch = None;
        self.ai_remove.failure = None;
        if offer.uploads && !self.extensions.uploads_allowed(&offer.extension) {
            self.ai_remove.consent = Some(Consent { offer, op });
            return;
        }
        self.start_ai_remove(offer, op);
    }

    /// The user's answer to the upload question: go on, or drop the request.
    pub(in crate::app) fn answer_ai_remove_consent(&mut self, allow: bool) {
        self.context.request_repaint();
        let Some(Consent { offer, op }) = self.ai_remove.consent.take() else {
            return;
        };
        if !allow {
            return;
        }
        if let Err(why) = self.extensions.allow_uploads(&offer.extension) {
            self.messages.fail(why);
            return;
        }
        // Checked again: the photo or the extension may have changed while asked.
        if let Some(why) = self.ai_remove_unavailable() {
            self.messages.warn(why);
            return;
        }
        self.start_ai_remove(offer, op);
    }

    fn start_ai_remove(&mut self, offer: Offer, op: RetouchOp) {
        let Some(image) = self.document.full().cloned() else {
            return;
        };
        if let Err(why) = self.extensions.retouch_ready(&offer) {
            self.messages.warn(why);
            return;
        }
        let (Some(ledger), Some(lifecycle)) = (
            self.extensions.mask_ledger(&offer.extension),
            self.extensions.mask_lifecycle(&offer.extension),
        ) else {
            self.messages
                .warn(format!("{} isn't installed", offer.extension));
            return;
        };
        let load = self.document.load_id();
        let recipe = self.document.edit.recipe().clone();
        let guard = self.ai_remove_guard(&image, &recipe);
        let ai = guard.ai.clone();
        let ai_denoise = ai.is_some();
        let (generation, cancel) = self.ai_remove.task.start();
        self.messages.note("Removing…");
        let job = retouch_generator::Prepare {
            load,
            generation,
            cancel: cancel.clone(),
            image,
            recipe,
            ai,
            op: op.clone(),
            ledger,
            generator: offer.generator.clone(),
        };
        self.ai_remove.pending = Some(Pending {
            offer,
            op,
            guard,
            load,
            generation,
            cancel,
            lifecycle,
            ai_denoise,
            sent: None,
        });
        let (tx, ctx) = (self.tx.clone(), self.context.clone());
        self.ai_remove.worker.call(
            move || retouch_generator::prepare(job),
            move || retouch_generator::done(load, generation, Err(stopped())),
            tx,
            ctx,
        );
    }

    /// A request has its region rendered: it is sent, unless it was given up
    /// on meanwhile, when its buffers are let go of.
    pub(in crate::app) fn retouch_prepared(&mut self, prepared: retouch_generator::Prepared) {
        let (load, generation) = (prepared.load, prepared.generation);
        let current = self.ai_remove.pending.as_ref().is_some_and(|p| {
            p.load == load
                && p.generation == generation
                && p.sent.is_none()
                && self.ai_remove.task.id() == generation
        });
        if !current || load != self.document.load_id() {
            return self.settle_ai_remove();
        }
        if self.void_ai_remove_if_moved() {
            return;
        }
        let ready = match prepared.result {
            Ok(ready) => ready,
            Err(failure) => {
                return self.ai_remove_done(Done {
                    load,
                    generation,
                    result: Err(failure),
                });
            }
        };
        let offer = self
            .ai_remove
            .pending
            .as_ref()
            .map(|p| p.offer.clone())
            .expect("checked above");
        let asked = ready.params.clone();
        match self
            .extensions
            .generate_retouch(&offer, ready.params, ready.buffers)
        {
            Ok(ticket) => {
                if let Some(pending) = self.ai_remove.pending.as_mut() {
                    pending.sent = Some(Sent {
                        ticket,
                        asked,
                        rendition: ready.rendition,
                        region: ready.region,
                    });
                }
            }
            Err(why) => self.ai_remove_done(Done {
                load,
                generation,
                result: Err(Failure::Failed(why)),
            }),
        }
    }

    /// The one outcome of retouch request `ticket`: its answer is inverted
    /// into a patch on the worker thread, its failure ends the request. An
    /// outcome nothing waits for any more is dropped, and its buffers with it.
    pub(in crate::app) fn retouch_answered(
        &mut self,
        extension: &str,
        ticket: u64,
        result: Result<Value, RemoteError>,
        buffers: Option<Returned>,
    ) {
        let Some(pending) = &mut self.ai_remove.pending else {
            return;
        };
        if pending.offer.extension != extension
            || pending.sent.as_ref().is_none_or(|s| s.ticket != ticket)
        {
            return self.settle_ai_remove();
        }
        let Some(sent) = pending.sent.take() else {
            return;
        };
        let (load, generation, cancel) = (pending.load, pending.generation, pending.cancel.clone());
        let provenance = pending.offer.provenance.clone();
        let ai_denoise = pending.ai_denoise;
        let answer = result
            .map_err(retouch_generator::failure)
            .and_then(|value| {
                let answer: RetouchGenerated = serde_json::from_value(value)
                    .map_err(|e| Failure::Failed(format!("the extension's answer: {e}")))?;
                answer.validate().map_err(|e| {
                    Failure::Failed(format!("the extension's answer: {}", e.message))
                })?;
                Ok(answer)
            });
        let (answer, buffers) = match (answer, buffers) {
            (Ok(answer), Some(buffers)) => (answer, buffers),
            (result, _) => {
                let failure = result.err().unwrap_or_else(|| {
                    Failure::Failed("the extension answered without its result".into())
                });
                return self.ai_remove_done(Done {
                    load,
                    generation,
                    result: Err(failure),
                });
            }
        };
        let job = retouch_generator::Finish {
            load,
            generation,
            cancel,
            asked: sent.asked,
            answer,
            buffers,
            rendition: sent.rendition,
            region: sent.region,
            provenance,
            ai_denoise,
        };
        let (tx, ctx) = (self.tx.clone(), self.context.clone());
        self.ai_remove.worker.call(
            move || retouch_generator::finish(job),
            move || retouch_generator::done(load, generation, Err(stopped())),
            tx,
            ctx,
        );
    }

    /// After the host's outcomes: a request whose extension moved on in its
    /// lifecycle is void, and one whose outcome can't come any more (gone
    /// from the host) ends now.
    pub(in crate::app) fn check_ai_remove(&mut self) {
        if self.void_ai_remove_if_moved() {
            return;
        }
        if let Some(Pending {
            offer,
            sent: Some(sent),
            load,
            generation,
            ..
        }) = &self.ai_remove.pending
            && !self
                .extensions
                .retouch_in_flight(&offer.extension, sent.ticket)
        {
            let done = Done {
                load: *load,
                generation: *generation,
                result: Err(Failure::Failed(format!(
                    "{} stopped before it answered",
                    offer.extension_name
                ))),
            };
            self.ai_remove_done(done);
        }
        // A consent question for an extension that can't run any more is moot.
        if let Some(consent) = &self.ai_remove.consent
            && let Err(why) = self.extensions.retouch_ready(&consent.offer)
            && !why.contains("credential store")
        {
            self.ai_remove.consent = None;
            self.messages.note(why);
        }
        self.settle_ai_remove();
    }

    /// Ends the running request at once if its extension has moved on in its
    /// lifecycle: busy clears, the worker's job is cancelled, a request sent
    /// is withdrawn and nothing is recorded. Returns whether it did.
    fn void_ai_remove_if_moved(&mut self) -> bool {
        let Some(pending) = &self.ai_remove.pending else {
            return false;
        };
        let now = self.extensions.mask_lifecycle(&pending.offer.extension);
        if now == Some(pending.lifecycle) {
            return false;
        }
        let name = pending.offer.extension_name.clone();
        self.ai_remove.cancel();
        self.messages
            .note(format!("AI Remove stopped: {name} was stopped"));
        self.settle_ai_remove();
        true
    }

    pub(in crate::app) fn cancel_ai_remove(&mut self) {
        self.context.request_repaint();
        self.ai_remove.cancel();
        self.settle_ai_remove();
        self.messages.note("AI Remove cancelled");
    }

    /// A request ended: its spot is added if it is still wanted and what it
    /// was made from still holds, else it is dropped.
    pub(in crate::app) fn ai_remove_done(&mut self, done: Done) {
        self.apply_ai_remove(done);
        self.settle_ai_remove();
    }

    fn apply_ai_remove(&mut self, done: Done) {
        let result = done.result;
        let current = self
            .ai_remove
            .pending
            .as_ref()
            .is_some_and(|p| p.load == done.load && p.generation == done.generation);
        if done.load != self.document.load_id()
            || done.generation != self.ai_remove.task.id()
            || !current
        {
            self.discard_generated_patch(result.ok());
            return;
        }
        self.ai_remove.task.finish(done.generation);
        let Some(pending) = self.ai_remove.pending.take() else {
            self.discard_generated_patch(result.ok());
            return;
        };
        let generated = match result {
            Ok(generated) => generated,
            // Its extension was disabled or stopped it.
            Err(Failure::Cancelled) => {
                self.messages.note("AI Remove stopped");
                return;
            }
            Err(failure) => {
                self.messages.fail(failure.message());
                self.ai_remove.failure = Some(failure);
                return;
            }
        };
        if self.extensions.mask_lifecycle(&pending.offer.extension) != Some(pending.lifecycle) {
            self.discard_generated_patch(Some(generated));
            return;
        }
        if self.ai_remove_guard_now().as_ref() != Some(&pending.guard)
            || self.document.edit.save_state().is_protected()
        {
            self.messages.warn(STALE);
            self.ai_remove.failure = Some(Failure::Failed(STALE.into()));
            self.discard_generated_patch(Some(generated));
            return;
        }
        // The patch, with every raster and patch the edit and its History hold.
        let edit = &self.document.edit;
        let history = edit.history().saved(edit.recipe());
        let held = history.mask_asset_ids();
        let ids: Vec<&str> = edit
            .recipe()
            .mask_asset_ids()
            .chain(held.iter().copied())
            .chain([generated.patch.id.as_str()])
            .collect();
        if crate::storage::mask_assets::decoded_bytes(ids) > crate::storage::mask_assets::EDIT_BYTES
        {
            self.messages
                .warn("This photo's masks and spots use too much memory for another AI Remove");
            self.discard_generated_patch(Some(generated));
            return;
        }
        if self.document.edit.recipe().retouch.len() >= crate::model::retouch::MAX_OPS {
            self.messages.warn("Too many spots on this photo");
            self.discard_generated_patch(Some(generated));
            return;
        }
        let mut op = pending.op;
        op.patch = Some(generated.patch);
        // Checked as a save will check it, so the edit never holds what it can't save.
        if let Err(why) = op.validate() {
            let id = op.patch.as_ref().map(|p| p.id.clone()).unwrap_or_default();
            self.messages.fail(format!("AI Remove failed: {why:#}"));
            self.ai_remove.failure = Some(Failure::Failed(format!("{why:#}")));
            self.discard_patch(&id);
            return;
        }
        // A drag still under way is recorded first, so undoing it keeps the spot,
        // and undoing the spot keeps the drag.
        if self.document.edit.history().in_gesture() {
            self.document.edit.finish_gesture();
        }
        let added = self.change_edit(Some(crate::app::history::Step::new("AI Remove", "")), |r| {
            r.add_retouch(op);
            r.retouch.len() - 1
        });
        self.view.retouch.selected = Some(added);
        self.messages.done("Removed");
    }

    /// Forgets the patch of a result the edit did not take.
    fn discard_generated_patch(&mut self, generated: Option<Generated>) {
        if let Some(generated) = generated {
            self.discard_patch(&generated.patch.id);
        }
    }

    /// Forgets an unsaved patch unless the edit, its History or Before still
    /// names it; decided once no request runs, as one may make the same one.
    fn discard_patch(&mut self, id: &str) {
        if self.ai_remove.pending.is_some() {
            self.ai_remove.deferred.push(id.to_string());
            return;
        }
        let edit = &self.document.edit;
        let named = edit.recipe().mask_asset_ids().any(|i| i == id)
            || edit
                .history()
                .saved(edit.recipe())
                .mask_asset_ids()
                .contains(id)
            || self
                .document
                .before
                .as_ref()
                .is_some_and(|r| r.mask_asset_ids().any(|i| i == id));
        if !named {
            crate::storage::mask_assets::discard_unsaved(id);
        }
    }

    /// Lets go of the patches set aside while a request ran, once none runs.
    fn settle_ai_remove(&mut self) {
        if self.ai_remove.pending.is_none() {
            for id in std::mem::take(&mut self.ai_remove.deferred) {
                self.discard_patch(&id);
            }
        }
    }
}

/// What a request whose worker job panicked, or whose worker is gone, ends in.
fn stopped() -> Failure {
    Failure::Failed("AI Remove stopped unexpectedly".into())
}

